        }
        for name in ["model_summary", "feature", "selection", "measure", "propose", "apply", "undo", "redo"] {
            assert!(names(Surface::Mcp).iter().any(|n| n == name), "MCP lists {name}");
        }
        assert!(!names(Surface::Assistant).iter().any(|n| n == "undo" || n == "extrude"));
